create table if not exists einvoice.invoice_documents (
  tenant_id uuid not null,
  electronic_invoice_id uuid not null,
  document_type text not null check (document_type in ('PDF', 'XML')),
  request_id uuid not null,
  status text not null
    check (status in ('PENDING', 'AVAILABLE', 'FAILED', 'CHECK_REQUIRED')),
  storage_reference text,
  checksum text,
  failure_code text,
  failure_message text,
  failure_source text
    check (failure_source is null or failure_source in ('PROVIDER', 'INTERNAL')),
  requested_at timestamptz not null default now(),
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  primary key (tenant_id, electronic_invoice_id, document_type),
  foreign key (tenant_id, electronic_invoice_id)
    references einvoice.electronic_invoices (tenant_id, id),
  check (
    status <> 'AVAILABLE'
    or (storage_reference is not null and checksum is not null)
  ),
  check (status not in ('FAILED', 'CHECK_REQUIRED') or failure_code is not null)
);

alter table einvoice.invoice_documents enable row level security;
revoke all on einvoice.invoice_documents from anon, authenticated;

insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
  'einvoice-documents',
  'einvoice-documents',
  false,
  20971520,
  array['application/pdf','application/xml','text/xml']
)
on conflict (id) do update set
  public = false,
  file_size_limit = excluded.file_size_limit,
  allowed_mime_types = excluded.allowed_mime_types;

drop policy if exists einvoice_documents_select on storage.objects;
create policy einvoice_documents_select
on storage.objects for select to authenticated
using (
  bucket_id = 'einvoice-documents'
  and cardinality(storage.foldername(name)) >= 2
  and iam.has_permission(
    case
      when (storage.foldername(name))[1]
        ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      then ((storage.foldername(name))[1])::uuid
      else null::uuid
    end,
    'einvoice.download_document'
  )
);

drop function if exists einvoice._invoice_document_command_id(uuid, integer);

create or replace function einvoice._invoice_document_command_id(
  p_request_id uuid
) returns uuid
language plpgsql
immutable
as $$
declare
  v_raw text;
  v_hex text;
begin
  v_raw := p_request_id::text || '|invoice_document';
  v_hex := encode(sha256(v_raw::bytea), 'hex');
  return (
    substr(v_hex, 1, 8) || '-' ||
    substr(v_hex, 9, 4) || '-' ||
    substr(v_hex, 13, 4) || '-' ||
    substr(v_hex, 17, 4) || '-' ||
    substr(v_hex, 21, 12)
  )::uuid;
end;
$$;

create or replace function einvoice._document_type_supported(
  p_capabilities jsonb,
  p_document_type text
) returns boolean
language sql
immutable
as $$
  select exists (
    select 1
    from jsonb_array_elements_text(
      coalesce(p_capabilities->'supported_document_types', '[]'::jsonb)
    ) elem
    where elem = p_document_type
  );
$$;

drop function if exists einvoice.request_invoice_document(uuid, uuid, uuid, text, varchar);

create or replace function einvoice.request_invoice_document(
  p_tenant_id uuid,
  p_actor_id uuid,
  p_sales_order_id uuid,
  p_document_type text
) returns table(
  request_id uuid,
  status text,
  storage_reference text,
  checksum text
) language plpgsql security definer set search_path = einvoice, iam, sales, public as $$
declare
  v_invoice einvoice.electronic_invoices%rowtype;
  v_connection einvoice.provider_connections%rowtype;
  v_document einvoice.invoice_documents%rowtype;
  v_request_id uuid;
  v_cmd_id uuid;
  v_doc_type text := upper(p_document_type);
begin
  if auth.uid() is null
     or p_actor_id is null
     or p_actor_id <> auth.uid()
     or not iam.has_permission(p_tenant_id, 'einvoice.view') then
    raise exception 'NO_PERMISSION: einvoice.view required';
  end if;

  if not sales.can_access_sales_order(
    p_tenant_id,
    p_actor_id,
    p_sales_order_id
  ) then
    raise exception 'NOT_FOUND: sales order not found';
  end if;

  if v_doc_type not in ('PDF', 'XML') then
    raise exception 'VALIDATION_ERROR: invalid document type';
  end if;

  select ei.*
  into v_invoice
  from einvoice.electronic_invoices ei
  where ei.tenant_id = p_tenant_id
    and ei.sales_order_id = p_sales_order_id
  for update;

  if not found then
    raise exception 'NOT_FOUND: electronic invoice not found';
  end if;

  select pc.*
  into v_connection
  from einvoice.provider_connections pc
  where pc.id = v_invoice.provider_connection_id
    and pc.tenant_id = p_tenant_id;

  if not einvoice._document_type_supported(v_connection.capabilities_snapshot, v_doc_type) then
    raise exception 'DOCUMENT_UNAVAILABLE: document type not supported by provider';
  end if;

  select d.*
  into v_document
  from einvoice.invoice_documents d
  where d.tenant_id = p_tenant_id
    and d.electronic_invoice_id = v_invoice.id
    and d.document_type = v_doc_type
  for update;

  if found and v_document.status in ('PENDING', 'AVAILABLE') then
    return query select
      v_document.request_id,
      v_document.status,
      v_document.storage_reference,
      v_document.checksum;
    return;
  end if;

  v_request_id := gen_random_uuid();

  insert into einvoice.invoice_documents as d (
    tenant_id, electronic_invoice_id, document_type, request_id, status, requested_at
  ) values (
    p_tenant_id, v_invoice.id, v_doc_type, v_request_id, 'PENDING', now()
  )
  on conflict (tenant_id, electronic_invoice_id, document_type) do update set
    request_id = excluded.request_id,
    status = 'PENDING',
    failure_code = null,
    failure_message = null,
    failure_source = null,
    completed_at = null,
    requested_at = now();

  v_cmd_id := einvoice._invoice_document_command_id(v_request_id);

  insert into einvoice.internal_commands (
    id, tenant_id, command_type, payload, source_event_id, enqueued_at
  ) values (
    v_cmd_id,
    p_tenant_id,
    'einvoice.download_invoice_document',
    jsonb_build_object(
      'tenant_id', p_tenant_id,
      'electronic_invoice_id', v_invoice.id,
      'document_type', v_doc_type,
      'request_id', v_request_id,
      'correlation_id', v_request_id
    ),
    v_cmd_id,
    now()
  ) on conflict (id) do nothing;

  return query select
    v_request_id,
    'PENDING'::text,
    null::text,
    null::text;
end;
$$;

drop function if exists einvoice.get_invoice_documents(uuid, uuid, uuid);

create or replace function einvoice.get_invoice_documents(
  p_tenant_id uuid,
  p_actor_id uuid,
  p_sales_order_id uuid
) returns table(
  pdf_available boolean,
  xml_available boolean,
  retrieval_status text,
  pdf_operation_id uuid,
  pdf_status text,
  pdf_storage_reference text,
  pdf_checksum text,
  pdf_failure_code text,
  xml_operation_id uuid,
  xml_status text,
  xml_storage_reference text,
  xml_checksum text,
  xml_failure_code text
) language plpgsql security definer set search_path = einvoice, public as $$
declare
  v_invoice einvoice.electronic_invoices%rowtype;
  v_connection einvoice.provider_connections%rowtype;
  v_pdf einvoice.invoice_documents%rowtype;
  v_xml einvoice.invoice_documents%rowtype;
  v_pdf_found boolean := false;
  v_xml_found boolean := false;
  v_retrieval_status text := 'PENDING';
begin
  if auth.uid() is null
     or p_actor_id is null
     or p_actor_id <> auth.uid()
     or not iam.has_permission(p_tenant_id, 'einvoice.view') then
    raise exception 'NO_PERMISSION: einvoice.view required';
  end if;

  if not sales.can_access_sales_order(
    p_tenant_id,
    p_actor_id,
    p_sales_order_id
  ) then
    raise exception 'NOT_FOUND: sales order not found';
  end if;

  select ei.*
  into v_invoice
  from einvoice.electronic_invoices ei
  where ei.tenant_id = p_tenant_id
    and ei.sales_order_id = p_sales_order_id;

  if not found then
    raise exception 'NOT_FOUND: electronic invoice not found';
  end if;

  select pc.*
  into v_connection
  from einvoice.provider_connections pc
  where pc.id = v_invoice.provider_connection_id
    and pc.tenant_id = p_tenant_id;

  select d.*
  into v_pdf
  from einvoice.invoice_documents d
  where d.tenant_id = p_tenant_id
    and d.electronic_invoice_id = v_invoice.id
    and d.document_type = 'PDF';
  v_pdf_found := found;

  select d.*
  into v_xml
  from einvoice.invoice_documents d
  where d.tenant_id = p_tenant_id
    and d.electronic_invoice_id = v_invoice.id
    and d.document_type = 'XML';
  v_xml_found := found;

  if (v_pdf_found and v_pdf.status = 'CHECK_REQUIRED')
     or (v_xml_found and v_xml.status = 'CHECK_REQUIRED') then
    v_retrieval_status := 'CHECK_REQUIRED';
  elsif (v_pdf_found and v_pdf.status = 'FAILED')
     and (not v_xml_found or v_xml.status = 'FAILED') then
    v_retrieval_status := 'FAILED';
  elsif (v_pdf_found and v_pdf.status = 'AVAILABLE')
     or (v_xml_found and v_xml.status = 'AVAILABLE') then
    v_retrieval_status := 'AVAILABLE';
  else
    v_retrieval_status := 'PENDING';
  end if;

  return query select
    einvoice._document_type_supported(v_connection.capabilities_snapshot, 'PDF'),
    einvoice._document_type_supported(v_connection.capabilities_snapshot, 'XML'),
    v_retrieval_status,
    case when v_pdf_found then v_pdf.request_id else null end,
    case when v_pdf_found then v_pdf.status else null end,
    case when v_pdf_found then v_pdf.storage_reference else null end,
    case when v_pdf_found then v_pdf.checksum else null end,
    case when v_pdf_found then v_pdf.failure_code else null end,
    case when v_xml_found then v_xml.request_id else null end,
    case when v_xml_found then v_xml.status else null end,
    case when v_xml_found then v_xml.storage_reference else null end,
    case when v_xml_found then v_xml.checksum else null end,
    case when v_xml_found then v_xml.failure_code else null end;
end;
$$;

drop function if exists einvoice.load_invoice_document_operation_context(uuid, uuid);

create or replace function einvoice.load_invoice_document_operation_context(
  p_tenant_id uuid,
  p_electronic_invoice_id uuid,
  p_document_type text,
  p_request_id uuid
) returns table(
  tenant_id uuid,
  electronic_invoice_id uuid,
  document_type text,
  request_id uuid,
  status text,
  provider_connection_id uuid,
  provider_invoice_reference text,
  invoice_series text
) language plpgsql security definer set search_path = einvoice, public as $$
begin
  if coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    nullif(current_setting('request.jwt.claim.role', true), '')
  ) is distinct from 'service_role' then
    raise exception 'NO_PERMISSION: service role required';
  end if;

  return query
  select
    d.tenant_id,
    d.electronic_invoice_id,
    d.document_type,
    d.request_id,
    d.status,
    ei.provider_connection_id,
    ei.provider_invoice_reference::text,
    ei.invoice_series::text
  from einvoice.invoice_documents d
  join einvoice.electronic_invoices ei
    on ei.tenant_id = d.tenant_id
   and ei.id = d.electronic_invoice_id
  where d.tenant_id = p_tenant_id
    and d.electronic_invoice_id = p_electronic_invoice_id
    and d.document_type = p_document_type
    and d.request_id = p_request_id;
end;
$$;

drop function if exists einvoice.record_invoice_document_result(
  uuid, uuid, text, bigint, uuid, bigint, text, text, text, text, bigint, text, text
);

create or replace function einvoice.record_invoice_document_result(
  p_tenant_id uuid,
  p_electronic_invoice_id uuid,
  p_document_type text,
  p_request_id uuid,
  p_status text,
  p_storage_reference text default null,
  p_checksum text default null,
  p_failure_code text default null,
  p_failure_message text default null,
  p_failure_source text default null
) returns table(
  request_id uuid,
  status text,
  storage_reference text,
  checksum text
) language plpgsql security definer set search_path = einvoice, public as $$
declare
  v_status text := upper(p_status);
  v_doc_type text := upper(p_document_type);
begin
  if coalesce(
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    nullif(current_setting('request.jwt.claim.role', true), '')
  ) is distinct from 'service_role' then
    raise exception 'NO_PERMISSION: service role required';
  end if;

  if v_status not in ('AVAILABLE', 'FAILED', 'CHECK_REQUIRED') then
    raise exception 'VALIDATION_ERROR: invalid invoice document result status';
  end if;

  if v_status = 'AVAILABLE' then
    if coalesce(trim(p_storage_reference), '') = ''
       or coalesce(trim(p_checksum), '') = '' then
      raise exception 'VALIDATION_ERROR: storage metadata required for AVAILABLE';
    end if;
  end if;

  update einvoice.invoice_documents d
  set
    status = v_status,
    storage_reference = case when v_status = 'AVAILABLE' then p_storage_reference else null end,
    checksum = case when v_status = 'AVAILABLE' then p_checksum else null end,
    failure_code = case when v_status = 'AVAILABLE' then null else p_failure_code end,
    failure_message = case when v_status = 'AVAILABLE' then null else p_failure_message end,
    failure_source = case when v_status = 'AVAILABLE' then null else p_failure_source end,
    completed_at = now()
  where d.tenant_id = p_tenant_id
    and d.electronic_invoice_id = p_electronic_invoice_id
    and d.document_type = v_doc_type
    and d.request_id = p_request_id
    and d.status = 'PENDING';

  return query
  select
    d.request_id,
    d.status,
    d.storage_reference,
    d.checksum
  from einvoice.invoice_documents d
  where d.tenant_id = p_tenant_id
    and d.electronic_invoice_id = p_electronic_invoice_id
    and d.document_type = v_doc_type;
end;
$$;

